$ErrorActionPreference='Stop'
$repo='C:\Users\PC\Desktop\CLIENTS\HONEST-ESTATE-WEBSITE';$source='C:\Users\PC\Desktop\CLIENTS\HONEST ESTATE DEVELOPERS RESOURCES';$brandDir=Join-Path $repo 'public\video-branding';$highlightDir=Join-Path $repo 'public\videos\2026\hed-highlights';$mpDir=Join-Path $repo 'public\videos\2026\mpambire';New-Item -ItemType Directory -Force -Path $highlightDir,$mpDir|Out-Null
function Add-EndCard([string]$sourcePath,[string]$destPath,[int]$targetW=0,[int]$targetH=0){$meta=(& ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 -- "$sourcePath").Trim().Split(',');$srcW=[int]$meta[0];$srcH=[int]$meta[1];if($targetW -le 0){$targetW=$srcW;$targetH=$srcH};$card=if($targetW -gt $targetH){Join-Path $brandDir 'hed-end-card-landscape.png'}else{Join-Path $brandDir 'hed-end-card-portrait.png'};$audio=(& ffprobe -v error -select_streams a:0 -show_entries stream=codec_name -of csv=p=0 -- "$sourcePath").Trim();$tmp=$destPath+'.tmp.mp4';if(Test-Path $tmp){Remove-Item $tmp -Force};$v0=('[0:v]scale={0}:{1}:force_original_aspect_ratio=decrease,pad={0}:{1}:(ow-iw)/2:(oh-ih)/2,fps=30,format=yuv420p,setpts=PTS-STARTPTS[v0]' -f $targetW,$targetH);$v1=('[1:v]scale={0}:{1},fps=30,format=yuv420p,setpts=PTS-STARTPTS[v1]' -f $targetW,$targetH);if($audio){$filter="$v0;$v1;[0:a]aresample=48000,aformat=sample_rates=48000:channel_layouts=stereo,asetpts=PTS-STARTPTS[a0];[2:a]asetpts=PTS-STARTPTS[a1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]";& ffmpeg -loglevel error -y -i "$sourcePath" -loop 1 -t 5 -i "$card" -f lavfi -t 5 -i 'anullsrc=r=48000:cl=stereo' -filter_complex $filter -map '[v]' -map '[a]' -c:v libx264 -preset veryfast -crf 24 -c:a aac -b:a 128k -movflags +faststart "$tmp"}else{$dur=(& ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 -- "$sourcePath").Trim();$filter="$v0;$v1;[2:a]asetpts=PTS-STARTPTS[a0];[3:a]asetpts=PTS-STARTPTS[a1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]";& ffmpeg -loglevel error -y -i "$sourcePath" -loop 1 -t 5 -i "$card" -f lavfi -t $dur -i 'anullsrc=r=48000:cl=stereo' -f lavfi -t 5 -i 'anullsrc=r=48000:cl=stereo' -filter_complex $filter -map '[v]' -map '[a]' -c:v libx264 -preset veryfast -crf 24 -c:a aac -b:a 128k -movflags +faststart "$tmp"};if($LASTEXITCODE -ne 0){throw "ffmpeg failed for $sourcePath"};Move-Item -Force $tmp $destPath}
$highlights=@(@('HED Property Experience 01 - Aerial View.mp4','hed-property-experience-01-aerial-view.mp4'),@('HED Property Experience 02 - Site Tour.mp4','hed-property-experience-02-site-tour.mp4'),@('HED Property Experience 03 - Property Briefing.mp4','hed-property-experience-03-property-briefing.mp4'),@('HED Property Experience 04 - Estate Presentation.mp4','hed-property-experience-04-estate-presentation.mp4'),@('HED Property Experience 05 - Field Visit.mp4','hed-property-experience-05-field-visit.mp4'))
foreach($item in $highlights){$src=Join-Path $source $item[0];$dst=Join-Path $highlightDir $item[1];Write-Output "Updating ending: $($item[0])";Add-EndCard $src $dst;$stem=[IO.Path]::GetFileNameWithoutExtension($item[1]);& ffmpeg -loglevel error -y -ss 3 -i "$dst" -frames:v 1 -q:v 2 (Join-Path $highlightDir ($stem+'-poster.jpg'))}
$mpSource=Join-Path $source 'HED MPAMBIRE ESTATE 2026';$mpambire=@(@('Drone video.mov.mp4','mpambire-drone-overview.mp4',1920,1080),@('Mpambire 1.mov.mp4','mpambire-site-visit-1.mp4',1280,720),@('Mpambire 3.mov.mp4','mpambire-site-visit-3.mp4',1280,720))
foreach($item in $mpambire){$src=Join-Path $mpSource $item[0];$dst=Join-Path $mpDir $item[1];Write-Output "Rebuilding from original: $($item[0])";Add-EndCard $src $dst $item[2] $item[3]}
Write-Output 'All 8 HED videos rebuilt with the single approved Call / WhatsApp number: 0744463708.'